Are you logging the pinhole like this?

```rust
self.recording_stream.log(
    format!("{}/projection", entity_path),
    &rerun::Pinhole::new(
        rerun::components::PinholeProjection::from_focal_length_and_principal_point(
            [intrinsics.fx, intrinsics.fy],
            [intrinsics.cx, intrinsics.cy],
        ),
    )
    .with_resolution([intrinsics.width as f32, intrinsics.height as f32]),
)?;
```
